import{_ as o,l,o as e,c as s,v as t,p as i,x as r,d as B,i as d,S as E}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"WSB 舆情因子","description":"","frontmatter":{"title":"WSB 舆情因子","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/wsb-sentiment-factor.md","filePath":"quant/wsb-sentiment-factor.md","lastUpdated":1789023840000}'),D={name:"quant/wsb-sentiment-factor.md"};function p(m,a,h,A,c,u){const n=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="wsb-舆情因子" tabindex="-1">WSB 舆情因子 <a class="header-anchor" href="#wsb-舆情因子" aria-label="Permalink to &quot;WSB 舆情因子&quot;">​</a></h1><div class="epigraph"><p>在 GameStop 事件之前，Wallstreetbets 上的尽职调查帖能够预测收益与现金流新闻；事件之后，强调价格压力与吸引注意的帖子占比上升，可预测性消失。</p><footer>—— Bradley, Hanousek, Jame and Xiao, Place Your Bets? The Value of Investment Research on Reddit’s Wallstreetbets, Review of Financial Studies, 2024</footer></div><p>社交媒体把散户讨论从消息板搬到可投票、可刷屏的广场。r/wallstreetbets（WSB）在 2021 年 1 月因 GameStop 成为公共基础设施，也把「舆情因子」从 Tetlock 式专栏推进到论坛文本与提及网络。Bradley、Hanousek、Jame 与 Xiao（2024）把 WSB 的尽职调查（DD）帖与普通提及分开，发现<strong>事件前有信息、事件后变注意游戏</strong>。公开文献中并不存在 Adams–Bloom–Ghent 合写的 WSB 经典论文；Baker、Bloom 与 Davis（2016）的 EPU 是报纸政策不确定，对象不是 Reddit。本篇以 Bradley 等为轴，辅以论坛情绪与提及量的工程口径，并接到 <a href="/quant/investor-attention-deg">Da–Engelberg–Gao 关注度</a> 与 <a href="/quant/news-nlp-alpha">舆情文本</a>。不讨论如何操纵版面或绕过平台规则。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>论坛文本同时装了三样东西：关于现金流的私人整理（DD）、关于涨跌的情绪极性、以及纯粹的显著（ticker 被喊到）。Antweiler 与 Frank（2004）在消息板上已经区分看涨言论与意见分歧。把三样东西压成一个「WSB 分数」再对收益回归，系数不可解释：GME 当周的提及爆炸是注意与协调，不是分析师修订。问题是分层测量，并承认<strong>样本在 2021 年 1 月断了</strong>——用户数、梗、版规与媒体覆盖同时换挡，全样本一个斜率会把两段机制平均掉。</p><p>第二句话是代表性。WSB 用户不是随机散户：更年轻、更杠杆、更偏期权，持仓集中在高 IVOL、高 MAX、低价名字。因子若在全市场截面上显著，往往是因为左边这组股票被重权，而不是因为论坛对 IBM 有定价权。评价应在可投资宇宙与「WSB 常客宇宙」上分开报。</p><h3 id="提及、极性与-dd-不是同一个因子" tabindex="-1">提及、极性与 DD 不是同一个因子 <a class="header-anchor" href="#提及、极性与-dd-不是同一个因子" aria-label="Permalink to &quot;提及、极性与 DD 不是同一个因子&quot;">​</a></h3><p><strong>提及量</strong>接近 Da 等的注意力：谁被喊到。可用去重用户数、帖子数、评论数；机器人与复读机要把同一用户重复喊单算一次。<strong>极性</strong>需要金融口语词表：rocket、puts、tendies、bagholder 不能靠通用情感词典。Loughran–McDonald 在 10-K 上有效，在 WSB 上会把 slang 读成中性或读错。<strong>DD 帖</strong>是 Bradley 等的识别：较长、带持仓与论点、被社区标成研究，而不是 meme。事件前 DD 预测随后收益与分析师/盈余新闻；事件后同类标签的帖更多在写「空头回补」与价格压力，预测力集中消失在这一子类。因此「WSB 情绪因子」若用全论坛词袋，测到的主要是注意与协调，不是 DD 的信息含量。</p><p><span class="marginnote">Karma、热帖算法与版主删除会把可观测文本变成平台筛选后的样本。用事后完整 dump 回测「当时能看到的热帖」，会高估信息到达速度。点-in-time 应保留爬取时刻的排序与已删除标记，而不是以今天的存档代替当时的广场。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>公司级日频。</strong> 抽取 ticker（处理 $GME 与 GME、括号、常见英文词误伤），在 \\(t\\) 日收盘前可获得的帖子上汇总：去重提及、极性净额、DD 虚拟变量或 DD 净推荐。特征在收盘锁定，预测 \\(t+1\\) 起的收益，避免用盘后发酵解释当日收益。控制上日收益、换手、新闻条数、<a href="/quant/investor-attention-deg">ASVI</a>、市值与行业。增量若只存在于未控 ASVI 时，则 WSB 只是搜索注意的一个下游喇叭。</p><p><strong>市场级。</strong> 把全论坛净极性或高热 ticker 的市值加权，做成零售情绪的日度代理，对照 <a href="/quant/baker-wurgler">Baker–Wurgler</a> 的月度指数与 Tetlock 专栏。频率不同：BW 解释截面投机性股票的相对定价，WSB 日度更像流量冲击。二者不要争「谁是真正的情绪」。</p><p><strong>样本切分。</strong> 预指定 GME 事件窗（例如 2021-01 前后），分别估计。Bradley 等的关键表是：事件前 DD 的预测在，事件后无；事件后价格压力类文本占比上升。复制若只报全样本，等于拒绝回答他们提出的问题。</p><h3 id="中性化、期权与迷因周" tabindex="-1">中性化、期权与迷因周 <a class="header-anchor" href="#中性化、期权与迷因周" aria-label="Permalink to &quot;中性化、期权与迷因周&quot;">​</a></h3><p>WSB 名字与 <a href="/quant/ivol-anomaly">IVOL</a>、<a href="/quant/max-effect">MAX</a>、低价、高换手高度重叠。原始多空会变成彩票组合。应在截面 rank 后对行业、市值、残差波动回归，见 <a href="/quant/cs-rank-features">特征 rank</a>。期权活跃周要把异常期权成交与股票收益分开：许多「WSB 收益」其实是短期 call 的 Delta 与 Gamma 涌入，现货只是一条腿。迷因周（单一 ticker 占论坛流量过高）应单独成组或剔除后报告，否则一个 GME 决定全年夏普。</p>',15)),(e(),i(E,null,{default:r(()=>[d(n,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20POST%5B%22WSB%20%E5%85%AC%E5%BC%80%E5%B8%96%22%5D%20--%3E%20DD%5B%22DD%20%E7%A0%94%E7%A9%B6%E7%B1%BB%22%5D%0A%20%20POST%20--%3E%20MEN%5B%22%E6%8F%90%E5%8F%8A%E9%87%8F%20%2F%20%E6%B3%A8%E6%84%8F%22%5D%0A%20%20POST%20--%3E%20POL%5B%22%E5%8F%A3%E8%AF%AD%E6%9E%81%E6%80%A7%22%5D%0A%20%20DD%20--%3E%20PRE%5B%22%E4%BA%8B%E4%BB%B6%E5%89%8D%EF%BC%9A%E9%A2%84%E6%B5%8B%E6%94%B6%E7%9B%8A%E4%B8%8E%E7%8E%B0%E9%87%91%E6%B5%81%E6%96%B0%E9%97%BB%22%5D%0A%20%20DD%20--%3E%20POSTG%5B%22%E4%BA%8B%E4%BB%B6%E5%90%8E%EF%BC%9A%E4%BF%A1%E6%81%AF%E5%90%AB%E9%87%8F%E4%B8%8B%E9%99%8D%22%5D%0A%20%20MEN%20--%3E%20FLOW%5B%22%E9%9B%B6%E5%94%AE%E6%B5%81%E4%B8%8E%E4%BB%B7%E6%A0%BC%E5%8E%8B%E5%8A%9B%22%5D%0A%20%20POL%20--%3E%20SENT%5B%22%E6%83%85%E7%BB%AA%E4%BB%A3%E7%90%86%EF%BC%8C%E5%99%AA%E5%A3%B0%E5%A4%A7%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>事件前的机制更接近「众包研究被低估」：一部分较长的 DD 整理了尚未被价格充分吸收的公开信息，散户跟随这些帖子交易，随后出现与现金流新闻同向的收益。事件后的机制更接近 Barber–Odean 注意与协调博弈：用户知道喊单可以吸引后来者，文本鼓励的是挤压与关注，而不是盈余。文化切换一旦发生，同样的爬虫和同样的词袋会从信息因子变成拥挤因子。这与 Da 等的搜索注意同族，但 WSB 多了<strong>内生协调</strong>：搜索是分散的查询，论坛是可见的共同知识。</p><p>意见分歧（看多看空同时刷屏）会抬成交与期权量，对收益的符号不稳定，这与 Antweiler–Frank 一致。把分歧当看涨信号，是把「有人在吵」当成「有人知道」。更干净的是把分歧当波动与换手的状态变量，把 DD 方向当（事件前的）信息，把提及残差当注意。</p><h3 id="与情绪指数、搜索注意的分工" tabindex="-1">与情绪指数、搜索注意的分工 <a class="header-anchor" href="#与情绪指数、搜索注意的分工" aria-label="Permalink to &quot;与情绪指数、搜索注意的分工&quot;">​</a></h3><p>Baker–Wurgler 用市场代理抽月度投机需求，不含 Reddit。EPU（Baker–Bloom–Davis）用报纸政策词，更不是 WSB。Da–Engelberg–Gao 的 SVI 是搜索注意，先于或并行于论坛。WSB 因子若还有增量，应出现在：控制 ASVI 与新闻后，DD 仍预测（事件前），或提及残差仍预测极短窗口的零售不平衡（事件后）。没有这两层对照，不宜宣称「发现了新的社交媒体溢价」。</p><p><span class="marginnote">把 2021 年 1 月的 GME 收益算进因子的样本外夏普，是把一次性协调事件当成可重复的 alpha。产品说明书若以该月为锚，测的是生存者叙事，不是预期收益。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>Adams–Bloom–Ghent 并非一篇可引用的 WSB 原论文；不要为了凑三人名字把 EPU 与 Reddit 焊在一起。不要用通用 NLP 极性代替 DD 分类。不要假设 API 今天能回放 2018 年的完整热帖排序。中文论坛（雪球、股吧）同构但词表、机器人与监管环境不同，应另文，不能把 RFS 的事件后结论直接写成「散户社交媒体一律无信息」。</p><p>容量与合规：即使事件前 DD 有纸面 IC，可交易性受限于那些名字的借券、期权流动性与平台审核延迟。作为风险仪表，WSB 提及拥挤对迷因敞口有用；作为可规模化因子，事件后证据弱。监管讨论的是披露与市场质量，不是把版面情绪写进月度再平衡。</p><p><span class="marginnote">出处：Bradley, Hanousek, Jame and Xiao, <em>Review of Financial Studies</em>, 2024。消息板见 Antweiler and Frank, 2004。EPU 见 Baker, Bloom and Davis, 2016，对象不是 WSB。注意力见 Da, Engelberg and Gao, 2011。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>WSB 文本应拆成 DD、极性与提及；混成单一「情绪分」无法对照机制。</li><li>Bradley 等表明：GME 之前 DD 有收益与现金流预测力，之后转向注意与价格压力，预测力消失。</li><li>公开文献中不存在作为 WSB 经典来源的 Adams–Bloom–Ghent 论文；EPU 是报纸政策不确定。</li><li>因子必须对 ASVI、MAX/IVOL、迷因周与期权流做对照，并预指定事件切分。</li><li>点-in-time 要保留当时可见的排序与删除，不能用事后 dump 代替广场。</li><li>出处：Bradley, Hanousek, Jame and Xiao, <em>RFS</em>, 2024；Antweiler and Frank, 2004；Da, Engelberg and Gao, 2011。</li></ul>',12))])}const f=o(D,[["render",p]]);export{g as __pageData,f as default};
